-- NEXORA FORGE ACADEMY INSTALL — PART 17/21
-- Curriculum lessons 253-270 of 324

begin;
insert into public.academy_lessons(id,course_id,title,slug,summary,content_html,starter_code,exercise,status,sort_order,estimated_minutes)
select x.id,c.id,x.title,x.slug,x.summary,x.content_html,x.starter_code,x.exercise,x.status,x.sort_order,x.estimated_minutes
from jsonb_to_recordset($lessons$[{"id":"curriculum-324-javascript-intermediate-01","course_id":"javascript-intermediate","title":"عبارت تابعی و تفاوت آن با اعلان تابع","slug":"javascript-intermediate-01","summary":"تابع را می‌توان در یک متغیر ذخیره کرد. عبارت تابعی تا زمان رسیدن اجرا به تعریف آن قابل استفاده نیست؛ این تفاوت در ترتیب بارگذاری اهمیت دارد.","content_html":"<h3>هدف درس</h3><p>زمان تعریف و قابل‌دسترسی شدن تابع را در عبارت تابعی بشناس.</p><h3>نمونه و بررسی</h3><p>قبل از خط تعریف، تابع را فراخوانی نکن و تفاوت آن را با function declaration آزمایش کن.</p><pre><code>const formatName = function (name) {\n  return name.trim().toUpperCase();\n};\nconsole.log(formatName(\"sara\"));</code></pre><h3>تمرین عملی</h3><p>یک تابع اعتبارسنجی ایمیل را به‌صورت عبارت تابعی در const ذخیره کن و پس از تعریف فراخوانی کن.</p><h3>نکته فنی</h3><p>عبارت تابعی معمولاً hoist نمی‌شود؛ متغیر const پیش از مقداردهی قابل استفاده نیست.</p><h3>معیار موفقیت</h3><p>تابع پس از تعریف اجرا شود و ورودی را طبق انتظار قالب‌بندی کند.</p>","starter_code":"const formatName = function (name) {\n  return name.trim().toUpperCase();\n};\nconsole.log(formatName(\"sara\"));","exercise":"یک تابع اعتبارسنجی ایمیل را به‌صورت عبارت تابعی در const ذخیره کن و پس از تعریف فراخوانی کن.","status":"published","sort_order":1,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-02","course_id":"javascript-intermediate","title":"قرارداد callback","slug":"javascript-intermediate-02","summary":"Callback تابعی است که به تابع دیگری داده می‌شود تا در زمان مشخص اجرا شود. قرارداد ورودی و خروجی آن باید روشن باشد.","content_html":"<h3>هدف درس</h3><p>تابع را به‌عنوان ورودی به تابع دیگر ارسال کن.</p><h3>نمونه و بررسی</h3><p>مشخص کن callback چه آرگومان‌هایی دریافت می‌کند و چند بار اجرا می‌شود.</p><pre><code>function processName(name, onReady) {\n  const clean = name.trim();\n  onReady(clean);\n}\nprocessName(\"  NEXORA  \", value =&gt; console.log(value));</code></pre><h3>تمرین عملی</h3><p>تابعی بساز که فهرست نام‌ها را بگیرد و پس از پاک‌سازی هر نام، callback را با نتیجه صدا بزند.</p><h3>نکته فنی</h3><p>callback باید تابع باشد؛ ارسال مقدار غیرتابع هنگام فراخوانی خطا ایجاد می‌کند.</p><h3>معیار موفقیت</h3><p>callback دقیقاً یک بار برای هر نام و با مقدار پاک‌سازی‌شده اجرا شود.</p>","starter_code":"function processName(name, onReady) {\n  const clean = name.trim();\n  onReady(clean);\n}\nprocessName(\"  NEXORA  \", value => console.log(value));","exercise":"تابعی بساز که فهرست نام‌ها را بگیرد و پس از پاک‌سازی هر نام، callback را با نتیجه صدا بزند.","status":"published","sort_order":2,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-03","course_id":"javascript-intermediate","title":"توابع مرتبه‌بالا","slug":"javascript-intermediate-03","summary":"تابع مرتبه‌بالا تابعی است که تابع می‌گیرد یا تابع برمی‌گرداند. این الگو برای ساخت رفتارهای قابل ترکیب مفید است.","content_html":"<h3>هدف درس</h3><p>تابعی بنویس که تابع دیگری تولید کند.</p><h3>نمونه و بررسی</h3><p>ورودی و خروجی تابع تولیدشده را مشخص کن.</p><pre><code>function makeMultiplier(factor) {\n  return number =&gt; number * factor;\n}\nconst double = makeMultiplier(2);\nconsole.log(double(9));</code></pre><h3>تمرین عملی</h3><p>تابعی بساز که ضریب تخفیف را دریافت کند و تابع محاسبه قیمت نهایی برگرداند.</p><h3>نکته فنی</h3><p>تابع بازگشتی می‌تواند به متغیرهای محدوده بیرونی دسترسی داشته باشد.</p><h3>معیار موفقیت</h3><p>تابع تولیدشده با چند ورودی نتیجه صحیح بدهد.</p>","starter_code":"function makeMultiplier(factor) {\n  return number => number * factor;\n}\nconst double = makeMultiplier(2);\nconsole.log(double(9));","exercise":"تابعی بساز که ضریب تخفیف را دریافت کند و تابع محاسبه قیمت نهایی برگرداند.","status":"published","sort_order":3,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-04","course_id":"javascript-intermediate","title":"تابع خالص و اثر جانبی","slug":"javascript-intermediate-04","summary":"تابع خالص با ورودی یکسان خروجی یکسان می‌دهد و بیرون از خود را تغییر نمی‌دهد. اثر جانبی مانند تغییر DOM یا نوشتن در storage باید آگاهانه مدیریت شود.","content_html":"<h3>هدف درس</h3><p>منطق محاسبه را از عملیات جانبی جدا کن.</p><h3>نمونه و بررسی</h3><p>داده مورد نیاز را به پارامتر بده و نتیجه را return کن.</p><pre><code>function addTax(price, rate) {\n  return price * (1 + rate);\n}\nconsole.log(addTax(100, 0.1));</code></pre><h3>تمرین عملی</h3><p>یک تابع محاسبه امتیاز را از بخش نمایش پیام جدا کن و بررسی کن تابع محاسبه وضعیت بیرونی را تغییر ندهد.</p><h3>نکته فنی</h3><p>تابع خالص تست واحد و استفاده مجدد را ساده‌تر می‌کند.</p><h3>معیار موفقیت</h3><p>دو بار اجرای تابع با ورودی یکسان نتیجه یکسان بدهد و متغیر بیرونی تغییر نکند.</p>","starter_code":"function addTax(price, rate) {\n  return price * (1 + rate);\n}\nconsole.log(addTax(100, 0.1));","exercise":"یک تابع محاسبه امتیاز را از بخش نمایش پیام جدا کن و بررسی کن تابع محاسبه وضعیت بیرونی را تغییر ندهد.","status":"published","sort_order":4,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-05","course_id":"javascript-intermediate","title":"Closure و حفظ وضعیت","slug":"javascript-intermediate-05","summary":"Closure زمانی شکل می‌گیرد که تابع به متغیرهای محدوده بیرونی خود حتی پس از پایان اجرای آن محدوده دسترسی داشته باشد.","content_html":"<h3>هدف درس</h3><p>وضعیت خصوصی را با تابع بازگشتی نگه دار.</p><h3>نمونه و بررسی</h3><p>متغیر count را بیرون از تابع بازگشتی در دسترس مستقیم قرار نده.</p><pre><code>function createCounter() {\n  let count = 0;\n  return () =&gt; ++count;\n}\nconst next = createCounter();\nconsole.log(next(), next(), next());</code></pre><h3>تمرین عملی</h3><p>تابعی بساز که شمارنده خصوصی برای هر دانش‌آموز ایجاد کند؛ دو شمارنده مستقل بساز.</p><h3>نکته فنی</h3><p>هر بار اجرای تابع سازنده، محیط closure جداگانه ایجاد می‌کند.</p><h3>معیار موفقیت</h3><p>دو شمارنده مستقل باشند و مقدار یکی روی دیگری اثر نگذارد.</p>","starter_code":"function createCounter() {\n  let count = 0;\n  return () => ++count;\n}\nconst next = createCounter();\nconsole.log(next(), next(), next());","exercise":"تابعی بساز که شمارنده خصوصی برای هر دانش‌آموز ایجاد کند؛ دو شمارنده مستقل بساز.","status":"published","sort_order":5,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-06","course_id":"javascript-intermediate","title":"بازگشت تابعی و recursion","slug":"javascript-intermediate-06","summary":"در recursion تابع خودش را با مسئله کوچک‌تر فراخوانی می‌کند. شرط پایه برای جلوگیری از فراخوانی بی‌پایان ضروری است.","content_html":"<h3>هدف درس</h3><p>مسئله را به زیرمسئله کوچک‌تر تقسیم کن.</p><h3>نمونه و بررسی</h3><p>شرط پایه را پیش از فراخوانی دوباره بنویس.</p><pre><code>function factorial(n) {\n  if (n &lt;= 1) return 1;\n  return n * factorial(n - 1);\n}\nconsole.log(factorial(5));</code></pre><h3>تمرین عملی</h3><p>تابع بازگشتی برای جمع اعداد از یک تا n بنویس و ورودی صفر را هم مدیریت کن.</p><h3>نکته فنی</h3><p>عمق زیاد recursion ممکن است به خطای stack overflow منجر شود.</p><h3>معیار موفقیت</h3><p>برای ورودی صفر، یک و چند مقدار بزرگ نتیجه درست و توقف قطعی داشته باشی.</p>","starter_code":"function factorial(n) {\n  if (n <= 1) return 1;\n  return n * factorial(n - 1);\n}\nconsole.log(factorial(5));","exercise":"تابع بازگشتی برای جمع اعداد از یک تا n بنویس و ورودی صفر را هم مدیریت کن.","status":"published","sort_order":6,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-07","course_id":"javascript-intermediate","title":"تبدیل مجموعه با map","slug":"javascript-intermediate-07","summary":"map از هر عنصر آرایه یک مقدار جدید می‌سازد و آرایه تازه‌ای با همان تعداد عضو برمی‌گرداند.","content_html":"<h3>هدف درس</h3><p>برای هر عضو آرایه یک مقدار تبدیل‌شده تولید کن.</p><h3>نمونه و بررسی</h3><p>تابع callback را بدون تغییر آرایه اصلی بنویس.</p><pre><code>const prices = [100, 250, 400];\nconst withTax = prices.map(price =&gt; price * 1.1);\nconsole.log(withTax, prices);</code></pre><h3>تمرین عملی</h3><p>آرایه‌ای از مدت زمان درس‌ها را به متن‌هایی مانند «۲۰ دقیقه» تبدیل کن.</p><h3>نکته فنی</h3><p>اگر هدف فقط اجرای اثر جانبی است، map انتخاب مناسبی نیست.</p><h3>معیار موفقیت</h3><p>آرایه خروجی هم‌اندازه ورودی باشد و آرایه اولیه تغییر نکند.</p>","starter_code":"const prices = [100, 250, 400];\nconst withTax = prices.map(price => price * 1.1);\nconsole.log(withTax, prices);","exercise":"آرایه‌ای از مدت زمان درس‌ها را به متن‌هایی مانند «۲۰ دقیقه» تبدیل کن.","status":"published","sort_order":7,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-08","course_id":"javascript-intermediate","title":"فیلتر شرطی با filter","slug":"javascript-intermediate-08","summary":"filter فقط عناصری را نگه می‌دارد که تابع شرط برای آن‌ها true برگرداند و آرایه جدید می‌سازد.","content_html":"<h3>هدف درس</h3><p>از یک آرایه زیرمجموعه مطابق شرط بساز.</p><h3>نمونه و بررسی</h3><p>شرط را در تابع کوتاه و قابل فهم بنویس.</p><pre><code>const scores = [42, 78, 91, 55, 66];\nconst passed = scores.filter(score =&gt; score &gt;= 60);\nconsole.log(passed);</code></pre><h3>تمرین عملی</h3><p>فهرست دوره‌ها را بر اساس published بودن فیلتر کن و آرایه اصلی را دست‌نخورده نگه دار.</p><h3>نکته فنی</h3><p>filter عضوها را تغییر نمی‌دهد، اما ارجاع به اشیای درون آرایه همچنان مشترک است.</p><h3>معیار موفقیت</h3><p>فقط عضوهای واجد شرط در خروجی باشند.</p>","starter_code":"const scores = [42, 78, 91, 55, 66];\nconst passed = scores.filter(score => score >= 60);\nconsole.log(passed);","exercise":"فهرست دوره‌ها را بر اساس published بودن فیلتر کن و آرایه اصلی را دست‌نخورده نگه دار.","status":"published","sort_order":8,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-09","course_id":"javascript-intermediate","title":"تجمیع داده با reduce","slug":"javascript-intermediate-09","summary":"reduce عناصر آرایه را به یک مقدار نهایی مانند عدد، شیء یا آرایه تجمیع می‌کند. مقدار اولیه accumulator اهمیت دارد.","content_html":"<h3>هدف درس</h3><p>چند مقدار را به یک نتیجه خلاصه تبدیل کن.</p><h3>نمونه و بررسی</h3><p>مقدار اولیه accumulator را صریح تعیین کن.</p><pre><code>const minutes = [12, 18, 25];\nconst total = minutes.reduce((sum, item) =&gt; sum + item, 0);\nconsole.log(total);</code></pre><h3>تمرین عملی</h3><p>تعداد درس‌های تکمیل‌شده را از آرایه‌ای از اشیا با reduce محاسبه کن.</p><h3>نکته فنی</h3><p>reduce روی آرایه خالی بدون مقدار اولیه خطا می‌دهد.</p><h3>معیار موفقیت</h3><p>جمع و شمارش با داده آزمایشی و آرایه خالی درست مدیریت شود.</p>","starter_code":"const minutes = [12, 18, 25];\nconst total = minutes.reduce((sum, item) => sum + item, 0);\nconsole.log(total);","exercise":"تعداد درس‌های تکمیل‌شده را از آرایه‌ای از اشیا با reduce محاسبه کن.","status":"published","sort_order":9,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-10","course_id":"javascript-intermediate","title":"جست‌وجو با find و findIndex","slug":"javascript-intermediate-10","summary":"find نخستین عضو مطابق شرط را برمی‌گرداند؛ findIndex موقعیت آن را می‌دهد. اگر موردی یافت نشود، به‌ترتیب undefined و ‎-1 برمی‌گردند.","content_html":"<h3>هدف درس</h3><p>مورد مشخصی را در آرایه پیدا کن.</p><h3>نمونه و بررسی</h3><p>حالت پیدا نشدن را قبل از استفاده از ویژگی‌های نتیجه بررسی کن.</p><pre><code>const users = [{id: 4, name: \"آوا\"}, {id: 7, name: \"نیما\"}];\nconst user = users.find(item =&gt; item.id === 7);\nconst index = users.findIndex(item =&gt; item.id === 7);\nconsole.log(user, index);</code></pre><h3>تمرین عملی</h3><p>دانش‌آموز را با شناسه یکتا پیدا کن و موقعیت او را نیز گزارش بده.</p><h3>نکته فنی</h3><p>find فقط نخستین تطبیق را برمی‌گرداند.</p><h3>معیار موفقیت</h3><p>شناسه موجود پیدا شود و شناسه ناموجود بدون خطا مدیریت شود.</p>","starter_code":"const users = [{id: 4, name: \"آوا\"}, {id: 7, name: \"نیما\"}];\nconst user = users.find(item => item.id === 7);\nconst index = users.findIndex(item => item.id === 7);\nconsole.log(user, index);","exercise":"دانش‌آموز را با شناسه یکتا پیدا کن و موقعیت او را نیز گزارش بده.","status":"published","sort_order":10,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-11","course_id":"javascript-intermediate","title":"مرتب‌سازی پایدار با comparator","slug":"javascript-intermediate-11","summary":"sort آرایه را درجا تغییر می‌دهد. برای عددها comparator لازم است تا مرتب‌سازی عددی به‌جای لغوی انجام شود.","content_html":"<h3>هدف درس</h3><p>ترتیب آرایه را با تابع مقایسه سفارشی تعیین کن.</p><h3>نمونه و بررسی</h3><p>برای ترتیب نزولی b - a و برای صعودی a - b را بررسی کن.</p><pre><code>const scores = [8, 100, 23, 4];\nconst sorted = [...scores].sort((a, b) =&gt; a - b);\nconsole.log(sorted, scores);</code></pre><h3>تمرین عملی</h3><p>فهرست دانش‌آموزان را بر اساس امتیاز نزولی مرتب کن و ترتیب آرایه اصلی را حفظ کن.</p><h3>نکته فنی</h3><p>sort آرایه اصلی را تغییر می‌دهد؛ پیش از آن کپی بساز.</p><h3>معیار موفقیت</h3><p>خروجی عددی درست مرتب شود و ورودی بدون تغییر بماند.</p>","starter_code":"const scores = [8, 100, 23, 4];\nconst sorted = [...scores].sort((a, b) => a - b);\nconsole.log(sorted, scores);","exercise":"فهرست دانش‌آموزان را بر اساس امتیاز نزولی مرتب کن و ترتیب آرایه اصلی را حفظ کن.","status":"published","sort_order":11,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-12","course_id":"javascript-intermediate","title":"تخت‌کردن آرایه‌های تو در تو","slug":"javascript-intermediate-12","summary":"flat یک سطح از آرایه‌های تو در تو را تخت می‌کند و flatMap ابتدا map و سپس تخت‌سازی یک‌سطحی انجام می‌دهد.","content_html":"<h3>هدف درس</h3><p>ساختار آرایه تو در تو را به خروجی تخت تبدیل کن.</p><h3>نمونه و بررسی</h3><p>عمق تخت‌سازی flat را متناسب با ساختار انتخاب کن.</p><pre><code>const groups = [[\"HTML\", \"CSS\"], [\"JS\"]];\nconsole.log(groups.flat());\nconst tags = [\"js\", \"css\"].flatMap(tag =&gt; [tag, tag.toUpperCase()]);\nconsole.log(tags);</code></pre><h3>تمرین عملی</h3><p>فهرست گروه‌های آموزشی را به یک فهرست واحد تبدیل و برای هر برچسب نسخه کوچک و بزرگ بساز.</p><h3>نکته فنی</h3><p>flat بدون آرگومان فقط یک سطح را تخت می‌کند.</p><h3>معیار موفقیت</h3><p>همه اعضای مورد انتظار در ترتیب درست قرار بگیرند.</p>","starter_code":"const groups = [[\"HTML\", \"CSS\"], [\"JS\"]];\nconsole.log(groups.flat());\nconst tags = [\"js\", \"css\"].flatMap(tag => [tag, tag.toUpperCase()]);\nconsole.log(tags);","exercise":"فهرست گروه‌های آموزشی را به یک فهرست واحد تبدیل و برای هر برچسب نسخه کوچک و بزرگ بساز.","status":"published","sort_order":12,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-13","course_id":"javascript-intermediate","title":"کپی سطحی و تغییرناپذیری","slug":"javascript-intermediate-13","summary":"کپی سطحی با spread فقط سطح اول را کپی می‌کند؛ اشیای تو در تو همچنان مرجع مشترک دارند.","content_html":"<h3>هدف درس</h3><p>یک نسخه تازه از داده بساز و تغییر را روی نسخه انجام بده.</p><h3>نمونه و بررسی</h3><p>برای سطح تو در تو نیز کپی مستقل بساز.</p><pre><code>const original = {name: \"سارا\", settings: {theme: \"light\"}};\nconst copy = {...original, name: \"مینا\"};\ncopy.settings = {...original.settings, theme: \"dark\"};\nconsole.log(original, copy);</code></pre><h3>تمرین عملی</h3><p>شیء تنظیمات را بدون تغییر شیء اصلی به‌روزرسانی کن و تفاوت کپی سطحی را نشان بده.</p><h3>نکته فنی</h3><p>spread برای داده تو در تو به‌تنهایی deep clone نیست.</p><h3>معیار موفقیت</h3><p>تغییر نسخه جدید روی شیء اصلی اثر نگذارد.</p>","starter_code":"const original = {name: \"سارا\", settings: {theme: \"light\"}};\nconst copy = {...original, name: \"مینا\"};\ncopy.settings = {...original.settings, theme: \"dark\"};\nconsole.log(original, copy);","exercise":"شیء تنظیمات را بدون تغییر شیء اصلی به‌روزرسانی کن و تفاوت کپی سطحی را نشان بده.","status":"published","sort_order":13,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-14","course_id":"javascript-intermediate","title":"تجزیه ساختاریافته با destructuring","slug":"javascript-intermediate-14","summary":"Destructuring مقدارهای آرایه یا ویژگی‌های شیء را به متغیرهای جدا می‌دهد و می‌تواند مقدار پیش‌فرض داشته باشد.","content_html":"<h3>هدف درس</h3><p>چند ویژگی را با یک دستور از شیء جدا کن.</p><h3>نمونه و بررسی</h3><p>برای تغییر نام متغیر از الگوی title: courseTitle استفاده کن.</p><pre><code>const course = {title: \"JavaScript\", level: \"intermediate\", language: \"fa\"};\nconst {title, level, duration = 20} = course;\nconsole.log(title, level, duration);</code></pre><h3>تمرین عملی</h3><p>از شیء پاسخ API نام، وضعیت و مقدار پیش‌فرض تصویر را استخراج کن.</p><h3>نکته فنی</h3><p>مقدار پیش‌فرض فقط هنگام undefined اعمال می‌شود، نه null.</p><h3>معیار موفقیت</h3><p>ویژگی‌های موجود و مقدار پیش‌فرض درست استخراج شوند.</p>","starter_code":"const course = {title: \"JavaScript\", level: \"intermediate\", language: \"fa\"};\nconst {title, level, duration = 20} = course;\nconsole.log(title, level, duration);","exercise":"از شیء پاسخ API نام، وضعیت و مقدار پیش‌فرض تصویر را استخراج کن.","status":"published","sort_order":14,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-15","course_id":"javascript-intermediate","title":"پارامترهای rest و spread","slug":"javascript-intermediate-15","summary":"rest چند آرگومان باقی‌مانده را در آرایه جمع می‌کند؛ spread آرایه یا شیء را در محل مصرف باز می‌کند.","content_html":"<h3>هدف درس</h3><p>تعداد متغیر ورودی‌ها را مدیریت کن.</p><h3>نمونه و بررسی</h3><p>rest باید آخرین پارامتر تعریف تابع باشد.</p><pre><code>function average(...values) {\n  return values.length ? values.reduce((sum, n) =&gt; sum + n, 0) / values.length : 0;\n}\nconsole.log(average(12, 16, 20));</code></pre><h3>تمرین عملی</h3><p>تابعی برای محاسبه میانگین تعداد نامشخصی از نمره‌ها بساز و آن را با آرایه spread فراخوانی کن.</p><h3>نکته فنی</h3><p>spread کپی عمیق ایجاد نمی‌کند.</p><h3>معیار موفقیت</h3><p>تابع با یک، چند و صفر ورودی رفتار تعریف‌شده داشته باشد.</p>","starter_code":"function average(...values) {\n  return values.length ? values.reduce((sum, n) => sum + n, 0) / values.length : 0;\n}\nconsole.log(average(12, 16, 20));","exercise":"تابعی برای محاسبه میانگین تعداد نامشخصی از نمره‌ها بساز و آن را با آرایه spread فراخوانی کن.","status":"published","sort_order":15,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-16","course_id":"javascript-intermediate","title":"دسترسی ایمن با optional chaining","slug":"javascript-intermediate-16","summary":"عملگر ?. پیش از دسترسی به ویژگی یا فراخوانی، null و undefined را بررسی می‌کند و از خطای دسترسی جلوگیری می‌کند.","content_html":"<h3>هدف درس</h3><p>دسترسی به مسیرهای احتمالیِ خالی را ایمن کن.</p><h3>نمونه و بررسی</h3><p>optional chaining را فقط جایی به کار ببر که نبودن داده قابل قبول است.</p><pre><code>const student = {profile: {name: \"آوا\"}};\nconsole.log(student.profile?.name);\nconsole.log(student.contact?.email);</code></pre><h3>تمرین عملی</h3><p>از پاسخ ناقص پروفایل، نام شهر و نشانی ایمیل اختیاری را بدون خطا بخوان.</p><h3>نکته فنی</h3><p>این عملگر خطای ساختار داده را پنهان نکند؛ داده ضروری را جداگانه اعتبارسنجی کن.</p><h3>معیار موفقیت</h3><p>مسیر موجود خوانده و مسیر ناموجود بدون TypeError مدیریت شود.</p>","starter_code":"const student = {profile: {name: \"آوا\"}};\nconsole.log(student.profile?.name);\nconsole.log(student.contact?.email);","exercise":"از پاسخ ناقص پروفایل، نام شهر و نشانی ایمیل اختیاری را بدون خطا بخوان.","status":"published","sort_order":16,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-17","course_id":"javascript-intermediate","title":"مقدار جایگزین با nullish coalescing","slug":"javascript-intermediate-17","summary":"عملگر ?? فقط برای null و undefined مقدار جایگزین می‌دهد؛ برخلاف || مقدارهای معتبر مانند صفر و رشته خالی را جایگزین نمی‌کند.","content_html":"<h3>هدف درس</h3><p>تفاوت مقدار خالی با مقدار صفر را در منطق پیش‌فرض‌گذاری رعایت کن.</p><h3>نمونه و بررسی</h3><p>برای مقدارهای عددی معتبر مانند صفر از ?? استفاده کن.</p><pre><code>const savedLimit = 0;\nconst limit = savedLimit ?? 10;\nconst fallback = savedLimit || 10;\nconsole.log(limit, fallback);</code></pre><h3>تمرین عملی</h3><p>برای شمارنده‌ای که صفر مقدار معتبر است، مقدار پیش‌فرض را با ?? تعیین کن.</p><h3>نکته فنی</h3><p>ترکیب ?? با && یا || بدون پرانتز مجاز نیست.</p><h3>معیار موفقیت</h3><p>صفر حفظ شود و فقط null یا undefined مقدار جایگزین بگیرند.</p>","starter_code":"const savedLimit = 0;\nconst limit = savedLimit ?? 10;\nconst fallback = savedLimit || 10;\nconsole.log(limit, fallback);","exercise":"برای شمارنده‌ای که صفر مقدار معتبر است، مقدار پیش‌فرض را با ?? تعیین کن.","status":"published","sort_order":17,"estimated_minutes":30},{"id":"curriculum-324-javascript-intermediate-18","course_id":"javascript-intermediate","title":"مجموعه یکتا با Set","slug":"javascript-intermediate-18","summary":"Set فقط یک نمونه از هر مقدار را نگه می‌دارد و برای حذف مقدارهای تکراری یا بررسی عضویت مناسب است.","content_html":"<h3>هدف درس</h3><p>تکرار مقدارهای اولیه را حذف کن.</p><h3>نمونه و بررسی</h3><p>برای بررسی عضویت از has استفاده کن.</p><pre><code>const tags = [\"html\", \"css\", \"html\", \"js\"];\nconst uniqueTags = [...new Set(tags)];\nconsole.log(uniqueTags);</code></pre><h3>تمرین عملی</h3><p>از آرایه شناسه‌های تکراری، فهرست یکتا بساز و وجود یک شناسه را بررسی کن.</p><h3>نکته فنی</h3><p>اشیای جداگانه با محتوای مشابه در Set همچنان دو مرجع متفاوت‌اند.</p><h3>معیار موفقیت</h3><p>تکرار رشته‌ها حذف و ترتیب ورود مقدارهای یکتا حفظ شود.</p>","starter_code":"const tags = [\"html\", \"css\", \"html\", \"js\"];\nconst uniqueTags = [...new Set(tags)];\nconsole.log(uniqueTags);","exercise":"از آرایه شناسه‌های تکراری، فهرست یکتا بساز و وجود یک شناسه را بررسی کن.","status":"published","sort_order":18,"estimated_minutes":30}]$lessons$::jsonb) as x(id text,course_id text,title text,slug text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer)
join (values
('html','html','beginner'),('html-intermediate','html','intermediate'),('html-advanced','html','advanced'),
('css','css','beginner'),('css-intermediate','css','intermediate'),('css-advanced','css','advanced'),
('javascript','javascript','beginner'),('javascript-intermediate','javascript','intermediate'),('javascript-advanced','javascript','advanced')
) as cp(course_id,language_id,level_id) on cp.course_id=x.course_id
join public.academy_courses c on c.language_id=cp.language_id and c.level_id=cp.level_id
on conflict(id) do update set title=excluded.title,slug=excluded.slug,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,archived_at=null,updated_at=now();
commit;
